import { CATEGORIES, COLORS, STATUS_LABELS, uid, createInitialState, createTrip, getActiveTrip, setItemStatus, updateItemQty, updateItemLocation, PACKING_LOCATIONS, addCustomItem, addGarmentsToTrip, addOutfitToTrip, suggestOutfits, validateState, GEAR_GROUPS, GEAR_CATALOG, getCatalogItems, catalogItemInTrip, addCatalogItems, addBoardPiece, addAllWardrobeToBoard, removeGarment, duplicateTrip, isItemRemembered, saveBoardOutfit, loadOutfitBoard } from './core.mjs?v=packing-v2';
