const KEY = 'snowpack.personal.v1';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sportNames = {snowboard:'单板', ski:'双板', both:'单板 + 双板'};
const categoryIcon = c => ({jacket:'jacket',pants:'pants',helmet:'helmet',goggles:'goggles',mid:'jacket',base:'jacket',camera:'camera',bag:'bag',snowboard:'snowboard',skis:'ski',poles:'ski',skiBoots:'shoe',snowboardBoots:'shoe',boots:'shoe'}[c] || 'hanger');
const sportIcon = sport => sport==='both'?icon('snowboard',15)+icon('ski',15):icon(sport,16);
const groupIcon = group => ({'滑行装备':'ski','穿戴':'jacket','护具':'helmet','随身':'bag','随身小物':'bag','随身与收纳':'bag','水与补给':'bag','补给':'bag','交通与自驾':'route','过夜':'moon','过夜与换洗':'moon','拍摄':'camera','出发检查':'ticket','自定义':'snowflake'}[group] || (group.includes('包')||group.includes('箱')||group.includes('袋')||group.includes('口袋')?'bag':group.includes('衣')||group.includes('穿')?'jacket':group.includes('拍摄')?'camera':group.includes('护')?'shield':'snowflake'));
const catalogByKey=new Map(GEAR_CATALOG.map(item=>[item.key,item]));
const catalogByName=new Map(GEAR_CATALOG.map(item=>[item.name,item]));
const colorFor = id => COLORS.find(c => c.id === id) || COLORS[0];
const readableColor = id => ['white','beige','yellow'].includes(id) ? '#81856d' : colorFor(id).hex;
const prepareBoard = value => !value.board && value.wardrobe.length ? addAllWardrobeToBoard(value) : value;
let cloudSync=null,syncUI=null,activePointers=0,deferredExternal=null,lastLocalRaw=null;
let state = createInitialState();
let storageProblem = '', damagedRaw = '', saveProblem = '';
try {
  const raw = localStorage.getItem(KEY);lastLocalRaw=raw;
  if (raw) { const saved = JSON.parse(raw); if (!validateState(saved)) throw new Error('数据格式不完整'); state = prepareBoard(saved); }
} catch (error) { storageProblem = '本机记录暂时无法读取。原记录仍然保留，请先导出备份，再恢复。'; try {damagedRaw = localStorage.getItem(KEY) || '';} catch {} }
let tab = ['packing','wardrobe','outfits'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'packing';
let filter = 'pending', packingStage = 'pack', packingGrouping = 'category', garmentFilter = 'all', wardrobeView='board', toastTimer, photoToken = 0, activeCutout=null, boardCleanup=null;
let boardHistory=createBoardHistory(),toastAction=null,lastNavTab=null;
let packingFocus=false;
try{packingFocus=localStorage.getItem('snowpack.packing-focus.v1')==='true';}catch{}
const modal = $('#modal');
$('#data-button').innerHTML = icon('settings');
$('#close-modal').innerHTML = icon('close');
function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';const label=dark?'切换浅色模式':'切换深色模式';$('#theme-button').innerHTML=icon(dark?'sun':'moon',20);$('#theme-button').setAttribute('aria-label',label);$('#theme-button').title=label;document.querySelector('meta[name="theme-color"]').content=dark?'#101012':'#f5f5f7';}
$('#theme-button').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('snowpack.theme.v1',next);}catch{}updateThemeButton();});
updateThemeButton();

function toast(message,action=null) { const el=$('#toast');el.innerHTML=`<span>${esc(message)}</span>${action?'<button type="button" data-toast-undo>撤销</button>':''}`;toastAction=action;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.classList.remove('visible');toastAction=null;},action?10000:4000); }
$('#toast').addEventListener('click',event=>{if(event.target.closest('[data-toast-undo]')&&toastAction){const action=toastAction;toastAction=null;action();}});
function save(next, message='', options={}) {
  if(!options.fromCloud&&!options.replaceLocal){
    try{const raw=localStorage.getItem(KEY);if(raw===null&&lastLocalRaw!==null)throw Error();if(raw!==lastLocalRaw&&raw){const disk=JSON.parse(raw);if(!validateState(disk))throw Error();{const base=lastLocalRaw?JSON.parse(lastLocalRaw):state;const merged=mergeStates(base,next,disk);if(!merged.state){toast('另一窗口修改了相同内容，未覆盖任何记录。请先保留当前输入，关闭后重新核对。');return false;}next=merged.state;options={...options,clearHistory:true};}}}
    catch{toast('另一窗口的记录暂时无法核对，这次修改尚未保存。');return false;}
  }
  next=prepareBoard(next);
  saveProblem='';
  if(storageProblem) {saveProblem='请先处理本机记录，再继续修改。';toast(saveProblem);return false;}
  if(!validateState(next)){saveProblem='这次修改未能保存，请检查内容后重试。';toast(saveProblem);return false;}
  try {const serialized=JSON.stringify(next);localStorage.setItem(KEY,serialized);lastLocalRaw=serialized;if(options.clearHistory)boardHistory=createBoardHistory();else if(options.recordHistory!==false)boardHistory=recordBoardChange(boardHistory,state,next);state=next;deferredExternal=null;if(!options.deferRender)render();if(message)toast(message);if(!options.fromCloud)cloudSync?.markChanged();return true;}
  catch {saveProblem='浏览器空间不足或不允许保存。这次修改未保存，请先导出备份或减少照片。';toast(saveProblem);return false;}
}
function travelBoard(direction){const result=travelBoardHistory(boardHistory,state,direction);if(!result)return false;if(!save(result.state,'',{recordHistory:false,deferRender:true}))return false;boardHistory=result.history;requestBoardFit();render();toast(direction==='undo'?'已撤销画板修改。':'已重做画板修改。');return true;}
function changeItemStatus(id,status){const before=state,item=getActiveTrip(state).items.find(i=>i.id===id);if(!item||item.status===status)return false;const next=setItemStatus(state,id,status),action=makeStatusUndo(before,next,id);if(!save(next))return false;toast(`${item.name} · ${item.category==='出发检查'?({pending:'待检查',packed:'已确认',skip:'本次不查'}[status]||STATUS_LABELS[status]):item.status==='rental'&&status==='packed'?'已取到，已备好':STATUS_LABELS[status]}`,()=>{const restored=undoItemStatus(state,action);if(!restored){toast('这件装备已再次修改，请从清单中核对。');return;}save(restored,`已撤销「${item.name}」的状态修改。`);});return true;}
function clone() { return structuredClone(state); }
function changeTrip(fn,message='') {const next=clone();const trip=getActiveTrip(next);fn(trip,next);return save(next,message);}
function showModal(title,body) {activeCutout?.abort();activeCutout=null;photoToken++;$('#modal-title').textContent=title;$('#modal-content').innerHTML=body;if(!modal.open)modal.showModal();}
function closeModal(){activeCutout?.abort();activeCutout=null;photoToken++;modal.close();flushExternal();cloudSync?.schedule();}
$('#close-modal').addEventListener('click',closeModal);
modal.addEventListener('cancel',()=>{activeCutout?.abort();activeCutout=null;photoToken++;cloudSync?.schedule();});
modal.addEventListener('close',flushExternal);
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
function setTab(next){tab=next;history.replaceState(null,'',`#${tab}`);render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{const key=location.hash.slice(1);if(['packing','wardrobe','outfits'].includes(key)){tab=key;render();}});
function receiveExternal(event){
 if(event.key!==KEY&&event.key!==null)return;
 if(activePointers||(modal.open&&!document.querySelector('[data-sync-panel]'))){deferredExternal={key:event.key,newValue:event.newValue};return;}
 try{const canonical=localStorage.getItem(KEY);if(canonical===lastLocalRaw)return;event={key:KEY,newValue:canonical};}catch{toast('暂时无法读取另一窗口的修改，本机画面已保留。');return;}
 boardHistory=createBoardHistory();toastAction=null;clearTimeout(toastTimer);$('#toast').classList.remove('visible');
 if(event.newValue===null){storageProblem='本机记录已在另一窗口清空。请先导出需要保留的记录，再刷新页面。';if(modal.open)closeModal();render();return;}
 try{const next=JSON.parse(event.newValue);if(!validateState(next))throw new Error('invalid');lastLocalRaw=event.newValue;state=prepareBoard(next);storageProblem='';if(modal.open)closeModal();render();cloudSync?.schedule();toast('其他窗口更新了记录，已同步到最新内容。');}catch{storageProblem='另一窗口写入了无法读取的记录。请先导出备份，再恢复。';if(modal.open)closeModal();render();}
}
function flushExternal(){if(deferredExternal&&!activePointers&&!modal.open){const event=deferredExternal;deferredExternal=null;receiveExternal(event);}}
window.addEventListener('storage',receiveExternal);

function render(){
  boardCleanup?.();boardCleanup=null;
  document.body.classList.toggle('is-board-page',tab==='wardrobe'&&wardrobeView==='board');
  document.body.classList.toggle('is-packing-page',tab==='packing');
  document.body.classList.toggle('is-packing-focus',tab==='packing'&&packingFocus);
  const focused=document.activeElement;
  const focusKeys=['tab','packingStage','packingGrouping','wardrobeView','filter','category','toggle','itemMenu','editGarment','packGarment','saveSuggestion','packOutfit','loadOutfit','action','piece','adjust','board'];
  const focusKey=focusKeys.find(key=>focused?.dataset?.[key]!==undefined);
  const focusValue=focusKey?focused.dataset[focusKey]:null;
  const visibleChecks=[...document.querySelectorAll('[data-toggle]')];
  const oldIndex=visibleChecks.indexOf(focused);
  if(lastNavTab!==tab){lastNavTab=tab;$('.bottom-nav').innerHTML=[['packing','bag','出发清单'],['wardrobe','jacket','装备画板'],['outfits','goggles','我的搭配']].map(([id,i,label])=>`<button class="nav-tab ${tab===id?'active':''}" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('');}
  if(storageProblem){$('#app').innerHTML=`<div class="error-banner"><h1>先保护好你的记录</h1><p>${storageProblem}</p><button class="secondary" data-action="data">打开备份与恢复</button></div>`;return;}
  $('#app').innerHTML=tab==='packing'?renderPacking():tab==='wardrobe'?renderWardrobe():renderOutfits();
  if(tab==='wardrobe'&&wardrobeView==='board')boardCleanup=mountBoard($('#app'),{getState:()=>state,save,editGarment:garmentDialog,addGarment:()=>garmentDialog(),saveOutfit:boardOutfitDialog,packGarments,undoBoard:()=>travelBoard('undo'),redoBoard:()=>travelBoard('redo'),canUndoBoard:Boolean(travelBoardHistory(boardHistory,state,'undo')),canRedoBoard:Boolean(travelBoardHistory(boardHistory,state,'redo')),getHistoryState:()=>({canUndoBoard:Boolean(travelBoardHistory(boardHistory,state,'undo')),canRedoBoard:Boolean(travelBoardHistory(boardHistory,state,'redo'))})});
  if(focusKey&&!modal.open){
    const attr='data-'+focusKey.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());
    const match=[...document.querySelectorAll('['+attr+']')].find(el=>el.dataset[focusKey]===focusValue);
    const checks=[...document.querySelectorAll('[data-toggle]')];
    const fallback=oldIndex>=0?(checks[Math.min(oldIndex,checks.length-1)]||document.querySelector('[data-filter="all"]')||document.querySelector('[data-packing-stage][aria-pressed="true"]')):null;
    (match||fallback)?.focus({preventScroll:true});
  }
}
function pageHead(kicker,title,desc,action,label,i='plus'){return `<div class="page-head"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="lead">${desc}</p></div><button class="primary" data-action="${action}">${icon(i,18)}${label}</button></div>`;}
function renderPacking(){
  const trip=getActiveTrip(state),readiness=getTripReadiness(trip),{gear,checks}=readiness;
  const isChecks=packingStage==='checks',isRental=packingStage==='rental';
  const scoped=trip.items.filter(item=>isChecks?item.category==='出发检查':item.category!=='出发检查'&&(!isRental||item.status==='rental'));
  const visible=isRental?scoped:scoped.filter(item=>filter==='all'||(filter==='pending'?(item.status==='pending'||item.status==='rental'):['packed','wearing'].includes(item.status)));
  const byBag=packingStage==='pack'&&packingGrouping==='bag';
  const groupFor=item=>byBag?(PACKING_LOCATIONS[item.packingLocation]||PACKING_LOCATIONS.unassigned):item.category;
  const grouped=new Map();for(const item of visible){const key=groupFor(item);if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(item);}
  const groups=byBag?[...Object.entries(PACKING_LOCATIONS).filter(([key])=>key!=='unassigned').map(([,label])=>label),PACKING_LOCATIONS.unassigned].filter(label=>grouped.has(label)):[...grouped.keys()];
  const progress=gear.total?Math.round(gear.ready/gear.total*100):0;
  const allChecked=gear.total+checks.total>0&&!gear.pending&&!gear.rental&&!checks.pending;
  const summary=allChecked?'本次清单已核对':!gear.pending&&!checks.pending&&gear.rental?`还有 ${gear.rental} 项装备需到场领取`:gear.total+checks.total?`${gear.pending} 项待装 · ${checks.pending} 项待检查`:gear.skipped+checks.skipped?'当前项目均已跳过':'先添加本次需要的装备与检查';
  const stageName=isChecks?'出发检查':isRental?'到场待取':'装备清单';
  const stageHelp=isChecks?'出发前逐项核对，检查完成后再勾选。':isRental?'实际取到装备后再勾选，未领取仍计入待准备。':'放好一件，再勾选一件。';
  const filters=[['pending',isChecks?'待检查':'还没带齐'],['all','全部'],['ready',isChecks?'已确认':'已备好']];
  return `${packingFocus?`<header class="packing-focus-header"><div class="packing-focus-top"><div class="packing-focus-title"><span>${icon('bag',19)}专注装包</span><h1>${esc(trip.name)}</h1></div><div class="packing-focus-actions"><button class="text-button" data-action="toggle-focus">退出专注</button><button class="icon-button" data-action="packing-more" aria-label="更多清单操作">${icon('more',20)}</button></div></div><p class="packing-focus-status" role="status">${allChecked?`${icon('check',16)}本次清单已核对`:`<strong>${gear.pending}</strong> 待装<span>·</span><strong>${checks.pending}</strong> 待检查<span>·</span><strong>${gear.rental}</strong> 待领取`}</p></header>`:`<div class="page-head packing-head"><div><h1>装好，再出发。</h1></div><button class="primary" data-action="toggle-focus">${icon('bag',19)}专注装包</button></div>`}
  <div class="pack-layout"><aside class="trip-column"><div class="trip-card compact-trip"><div class="trip-mountain" aria-hidden="true">${icon('mountain',70)}</div>
    <div class="trip-top"><button class="trip-switch" data-action="trips" aria-label="切换行程"><strong class="trip-name">${esc(trip.name)}</strong>${icon('down',17)}</button><div class="trip-entry-actions"><button class="text-button reuse-trip" data-action="reuse-trip">${icon('refresh',15)}沿用</button><button class="text-button reuse-trip" data-action="new-trip">${icon('plus',15)}新出发</button></div></div>
    <div class="trip-meta"><span class="sport-meta">${sportIcon(trip.sport)}${sportNames[trip.sport]}</span><span>${trip.overnight?'过夜出行':'当天往返'}</span></div>
    <div class="readiness-summary" aria-label="本次准备情况"><div><span>装备已备</span><strong>${gear.ready}<small> / ${gear.total}</small></strong></div><div><span>检查已确认</span><strong>${checks.ready}<small> / ${checks.total}</small></strong></div><div><span>到场待取</span><strong>${gear.rental}<small> 项</small></strong></div></div>
    <div class="readiness-progress progress-track" role="progressbar" aria-label="装备准备进度，不含出发检查" aria-valuenow="${progress}" aria-valuemin="0" aria-valuemax="100" aria-valuetext="${gear.ready} 项装备已备，共 ${gear.total} 项，其中 ${gear.rental} 项到场待取"><i style="width:${progress}%"></i></div><p class="readiness-note ${allChecked?'complete':''}">${summary}${gear.skipped||checks.skipped?`<span>${[gear.skipped?gear.skipped+' 项不带':'',checks.skipped?checks.skipped+' 项不查':''].filter(Boolean).join(' · ')}</span>`:''}</p>
  </div><div class="sidebar-note"><strong>放好一件，勾选一件。</strong>右侧「···」可改数量、标记穿身上或租借。<br>沿用这份清单，下一次就不用重新选。</div></aside>
  <section aria-label="${stageName}"><div class="packing-stages" role="group" aria-label="核对阶段">${[['pack','装包',gear.pending+gear.rental],['checks','出发检查',checks.pending],['rental','到场待取',gear.rental]].map(([id,label,count])=>`<button type="button" class="packing-stage ${packingStage===id?'active':''}" data-packing-stage="${id}" aria-pressed="${packingStage===id}" aria-controls="packing-items">${icon({pack:'bag',checks:'ticket',rental:'mountain'}[id],16)}${label}<span aria-label="${count} 项待核对">${count}</span></button>`).join('')}</div><div class="packing-tools"><div class="packing-view-bar"><p class="packing-stage-help">${stageHelp}</p>${packingStage==='pack'?`<div class="packing-grouping" role="group" aria-label="装备分组方式">${[['category','按类别'],['bag','按包']].map(([id,label])=>`<button type="button" data-packing-grouping="${id}" aria-pressed="${packingGrouping===id}" class="${packingGrouping===id?'active':''}">${label}</button>`).join('')}</div>`:''}</div><div class="packing-controls"><div class="list-toolbar">${isRental?`<p class="rental-queue-count">${gear.rental} 项待领取</p>`:`<div class="filters" aria-label="筛选${stageName}">${filters.map(([id,label])=>`<button class="filter ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>`}<button class="add-item" data-action="add-item">${icon('plus',16)}${isChecks?'加检查':'加装备'}</button></div><div class="packing-links"><button class="text-button" data-action="scenarios">${icon('route',16)}场景补齐</button><button class="text-button" data-action="catalog">${icon('bag',16)}装备库</button><button class="text-button" data-action="reset">${icon('refresh',14)}重新核对</button></div></div></div>
  <div id="packing-items">${groups.length?groups.map((group,index)=>`<section class="gear-group"><div class="group-head"><span class="group-symbol" aria-hidden="true">${icon(groupIcon(group),18)}</span><span class="group-number">${String(index+1).padStart(2,'0')}</span><h2>${esc(group)}</h2><small>${grouped.get(group).length} 项</small></div><div class="gear-list">${grouped.get(group).map(renderItem).join('')}</div></section>`).join(''):renderPackingEmpty(readiness,scoped,allChecked)}</div>
  <p class="list-foot">${icon('shield',13)}记录先保存在本机，右上角可连接设备同步或导出备份。此清单适用于雪场内滑行。</p></section></div>`;
}
function renderPackingEmpty({gear,checks},scoped,allChecked){
  let title,description,action='';
  if(packingStage==='rental'){
    title='暂无到场待取的装备';description=allChecked?'本次清单已核对，可回「装包」查看已备装备。':'租借的装备可在「装包」中通过右侧「···」标记。';
  }else if(packingStage==='checks'){
    if(!scoped.length){title='还没有加入出发检查';description='从装备库选入本次需要核对的项目。';action='<button class="secondary" data-action="catalog">去装备库添加检查</button>';}
    else if(filter==='ready'){title='还没有确认的检查';description='完成实际检查后再勾选，可切换「待检查」继续。';}
    else if(!checks.total){title='本次检查均已标记不查';description='可切换「全部」，恢复本次需要的检查项。';}
    else{title='本次检查已确认';description=gear.pending||gear.rental?`还有 ${gear.pending} 项待装、${gear.rental} 项到场待取。`:'本次清单已核对，可切换「全部」再检查一次。';}
  }else if(!scoped.length){title='还没有加入装备';description='添加本次要带的装备，或从装备库中选择。';}
  else if(filter==='ready'){title='还没有备好的装备';description='放好一件再勾选，可切换「还没带齐」继续。';}
  else if(!gear.total){title='本次装备均已标记不带';description='可切换「全部」，恢复本次需要的装备。';}
  else{title=allChecked?'本次清单已核对':'装备已备齐';description=checks.pending?`还有 ${checks.pending} 项出发检查待确认。`:'可切换「全部」再检查一次，看看有没有误标。';}
  return `<div class="empty-mini packing-empty">${icon(packingStage==='rental'||filter==='ready'?'bag':'check',32)}<h2>${title}</h2><p>${description}</p>${action}</div>`;
}
function renderItem(item){const done=['packed','wearing'].includes(item.status);const check=item.category==='出发检查';const note=(catalogByKey.get(item.templateKey)||catalogByName.get(item.name))?.note;const garment=state.wardrobe.find(g=>g.id===item.wardrobeId);const location=!check&&item.packingLocation?PACKING_LOCATIONS[item.packingLocation]:'';return `<div class="gear-row ${done?'done':''} ${item.status==='skip'?'skip':''}"><button class="gear-check" data-toggle="${esc(item.id)}" role="checkbox" aria-checked="${done}" aria-label="${esc(item.name)}，${done?(check?'改为待检查':'改为待装'):item.status==='skip'?'恢复此项':check?'实际检查后标记已确认':item.status==='rental'?'实际取到后标记已备好':'标记已装包'}"><span class="check-mark">${done?icon('check',16):item.status==='skip'?'<span>−</span>':''}</span></button>${garment?.photo?`<img loading="lazy" decoding="async" class="mini-photo" src="${garment.cutout||garment.photo}" alt="">`:''}<div class="gear-copy"><p class="gear-name">${esc(item.name)}</p><p class="gear-sub">${location?`${esc(location)} · `:''}${item.qty>1?`数量 ${item.qty} · `:''}${item.status==='rental'&&!check?'实际取到装备后再勾选':check?(note?esc(note):'实际检查后再打勾'):item.source==='wardrobe'?'来自我的衣橱':item.source==='custom'&&!item.templateKey?'自定义装备':note?esc(note):'放进包里再打勾'}</p></div><span class="status-tag ${item.status}">${check?(done?'已确认':item.status==='skip'?'本次不查':'待检查'):STATUS_LABELS[item.status]}</span><button class="row-more" data-item-menu="${esc(item.id)}" aria-label="${esc(item.name)}的状态和数量${check?'':'及收纳位置'}">${icon('more',18)}</button></div>`;}
function renderWardrobe(){const modes=`<div class="wardrobe-mode" aria-label="衣橱视图"><button data-wardrobe-view="board" class="${wardrobeView==='board'?'active':''}" aria-pressed="${wardrobeView==='board'}">自由画板</button><button data-wardrobe-view="list" class="${wardrobeView==='list'?'active':''}" aria-pressed="${wardrobeView==='list'}">单品管理</button></div>`;return wardrobeView==='board'?`${pageHead('YOUR GEAR CANVAS','装备，上墙。','让雪服、雪板和小配件，在这里自由组合。','add-garment','加装备照片','camera')}${modes}${renderBoard(state)}<p class="form-note">画板与照片先保存在本机，右上角可连接设备同步或导出备份。选择装备后点「编辑」可重新抠图，处理前照片的压缩版本始终保留。</p>`:`${modes}${renderWardrobeList()}`;}
function packGarments(ids){
  const wanted=[...new Set(ids)].filter(id=>state.wardrobe.some(g=>g.id===id));
  if(!wanted.length){toast('先选择要加入的装备。');return false;}
  const before=getActiveTrip(state),missing=wanted.filter(id=>!before.items.some(i=>i.wardrobeId===id&&i.status!=='skip'));
  if(!missing.length){toast('这些装备已在本次清单，已装状态保留。');return true;}
  const next=addGarmentsToTrip(state,wanted),after=getActiveTrip(next);
  const added=missing.filter(id=>after.items.some(i=>i.wardrobeId===id&&i.status!=='skip')).length;
  if(!added){toast('本次清单已满，未能加入装备。');return false;}
  return save(next,`已加入「${before.name}」${added} 件，新增装备待装。${added<missing.length?'部分装备因清单容量限制未加入。':''}`);
}
function garmentCard(g){
  const included=getActiveTrip(state).items.some(i=>i.wardrobeId===g.id&&i.status!=='skip');
  return `<article class="garment-card"><button class="garment-edit" data-edit-garment="${esc(g.id)}" aria-label="编辑${esc(g.name)}"><div class="garment-photo">${garmentVisual(g)}${g.photo?'':'<small>还没放照片</small>'}</div><div class="garment-info"><h3>${esc(g.name)}</h3><p><i class="color-dot" style="background:${colorFor(g.color).hex}"></i>${colorFor(g.color).label} · ${CATEGORIES[g.category]}</p></div></button><button class="garment-pack ${included?'included':''}" data-pack-garment="${esc(g.id)}" ${included?'disabled':''} aria-label="${esc(g.name)}，${included?'已在本次清单':'加入本次清单'}">${icon(included?'check':'bag',16)}${included?'已在本次清单':'加入本次清单'}</button></article>`;
}
function renderWardrobeList(){const filtered=state.wardrobe.filter(g=>garmentFilter==='all'||g.category===garmentFilter);return `${pageHead('YOUR SNOW WARDROBE','穿你喜欢的那套。','把已有的雪服放在一起，出发前看着选。','add-garment','加一件')}${state.wardrobe.length?`<div class="wardrobe-toolbar">${[['all','全部'],...Object.entries(CATEGORIES)].map(([id,label])=>`<button class="category-chip ${garmentFilter===id?'active':''}" data-category="${id}" aria-pressed="${garmentFilter===id}">${label}${id==='all'?` · ${state.wardrobe.length}`:''}</button>`).join('')}</div><div class="garment-grid">${filtered.map(garmentCard).join('')}</div>${filtered.length?'':'<div class="empty-mini"><p>这一类还没有单品，点「加一件」放进来。</p></div>'}`:`<div class="empty-wardrobe"><div><h2>先放进来一件外套，<br>再配一条雪裤。</h2><p>照片、名字、颜色，就够了。<br>不用一次把整个衣橱录完。</p><button class="primary" data-action="add-garment">${icon('camera',18)}添加第一件</button></div><div class="closet-illustration" aria-hidden="true"><div class="illustration-card">${icon('jacket')}雪服外套</div><div class="illustration-card">${icon('pants')}雪裤</div></div></div>`}<div class="info-strip">从你常穿的雪服开始录入。这里的单品需要由你录入；没有照片也能先按颜色组合。照片先保存在本机，连接设备同步后会同步至你的私有空间。</div>`;}
function garmentVisual(g){return (g.cutout||g.photo)?`<img loading="lazy" decoding="async" src="${g.cutout||g.photo}" alt="${esc(g.name)}">`:`<span style="color:${readableColor(g.color)}">${icon(categoryIcon(g.category),64)}</span>`;}
function renderOutfits(){const suggestions=suggestOutfits(state.wardrobe);return `${pageHead('A GOOD PAIRING','今天，这样搭。','只从已有单品中选，喜欢的那套直接加入清单。','build-outfit','自由搭一套','hanger')}<div class="section-title"><h2>我存好的搭配</h2><span>${state.outfits.length} 套</span></div>${state.outfits.length?`<div class="outfit-grid">${state.outfits.map(o=>renderOutfit(o,false)).join('')}</div>`:`<div class="empty-mini">${icon('hanger',30)}<h2>给下一次出发留一套。</h2><p>${state.wardrobe.length?'自由选择单品，或者收藏下方的配色建议。':'先在雪服衣橱加一件外套和一条雪裤，就能看到组合。'}</p><button class="text-button" data-tab="wardrobe">去雪服衣橱 ${icon('arrow',16)}</button></div>`}<div class="section-title"><h2>从已有衣服里找搭配</h2><span>配色建议</span></div>${suggestions.length?`<div class="outfit-grid">${suggestions.map((o,index)=>renderOutfit({...o,id:String(index),name:`${colorFor(state.wardrobe.find(g=>g.id===o.garmentIds[0])?.color).label}外套的搭配`},true)).join('')}</div><p class="info-strip">这些建议依据你录入的颜色组合，不是虚拟试穿。照片方便你判断版型和配色；保暖程度、镜片适用光线仍按实际装备与天气选择。</p>`:`<p class="info-strip">还需要至少一件「雪服外套」和一条「雪裤」。录入后会出现配色建议，也可以先自由组合已有的其他单品。</p>`}`;}
function renderOutfit(outfit,suggested){const garments=outfit.garmentIds.map(id=>state.wardrobe.find(g=>g.id===id)).filter(Boolean);return `<article class="outfit-card"><div class="outfit-visual">${garments.map(g=>`<div class="outfit-piece">${garmentVisual(g)}<small>${esc(g.name)}</small></div>`).join('')}</div><div class="outfit-info"><h3>${esc(outfit.name)}</h3><p>${suggested?esc(outfit.reason):`${garments.length} 件已有单品${outfit.board?' · 已保存画板布局':''}`}</p><div class="outfit-actions">${suggested?`<button class="secondary" data-save-suggestion="${outfit.id}">${icon('plus',15)}存这套</button>`:`<button class="primary" data-pack-outfit="${esc(outfit.id)}">${icon('bag',16)}加入清单</button><button class="secondary" data-load-outfit="${esc(outfit.id)}">${icon('hanger',16)}打开画板</button><button class="icon-button" data-delete-outfit="${esc(outfit.id)}" aria-label="删除搭配${esc(outfit.name)}">${icon('trash',16)}</button>`}</div></div></article>`;}

function reuseTripDialog(){
 const source=getActiveTrip(state),skipped=source.items.filter(i=>i.status==='skip').length,rental=source.items.filter(i=>i.status==='rental').length;
 showModal('照这份，再出发。',`<form id="reuse-trip-form"><p class="small-note">沿用「${esc(source.name)}」的装备、数量和衣橱单品，原行程保留。</p><div class="field modal-section"><label for="reuse-name">新行程名称</label><input id="reuse-name" name="name" maxlength="80" value="${esc((source.name+' · 再出发').slice(0,80))}" required></div><div class="reuse-summary">${sportNames[source.sport]} · ${source.overnight?'过夜':'日归'} · ${source.items.length} 项</div><label class="inline-field"><input type="checkbox" name="keepSkipped" checked>沿用「本次不带」的 ${skipped} 项</label><label class="inline-field"><input type="checkbox" name="keepRental" checked>沿用「到场待取」的 ${rental} 项</label><p class="form-note">已装包、穿身上和已确认的检查项都会恢复待核对。取消上面的选项，相应装备也会恢复待装。</p><button class="primary full-button" type="submit">生成新的待核对清单</button></form>`);
 $('#reuse-trip-form').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);if(state.trips.length>=100){toast('行程已达上限，请先导出备份。');return;}if(state.activeTripId!==source.id){toast('当前行程已改变，请重新选择。');return;}const next=duplicateTrip(state,{name:f.get('name').trim(),keepSkipped:f.has('keepSkipped'),keepRental:f.has('keepRental')});if(next===state){toast('未能生成新行程，请检查名称。');return;}if(save(next,'已沿用装备和数量，请重新逐件核对。')){filter='pending';packingStage='pack';closeModal();setTab('packing');}});
}
function boardOutfitDialog(garmentIds){
 const selected=garmentIds.map(id=>state.wardrobe.find(g=>g.id===id)).filter(Boolean);if(!selected.length||selected.length>30){toast('每套请选择 1–30 件装备。');return;}
 showModal('把这套，留给下次。',`<form id="board-outfit-form"><div class="saved-selection">${selected.map(g=>`<div>${garmentVisual(g)}<span>${esc(g.name)}</span></div>`).join('')}</div><div class="field"><label for="board-outfit-name">搭配名称</label><input id="board-outfit-name" name="name" maxlength="120" placeholder="比如：周末绿色那套" required></div><label class="inline-field"><input type="checkbox" name="pack" checked>同时加入「${esc(getActiveTrip(state).name)}」清单</label><p class="form-note">保存这 ${selected.length} 件的摆放位置、大小与角度。加入清单后，仍需实际装包再勾选。</p><button class="primary full-button" type="submit">存好这套</button></form>`);
 $('#board-outfit-form').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);let next=saveBoardOutfit(state,{name:f.get('name').trim(),garmentIds});if(next===state){toast(state.outfits.length>=200?'搭配已达上限，请先整理已有搭配。':'没有可保存的装备，请重新选择。');return;}let packed=false;if(f.has('pack')){const withItems=addOutfitToTrip(next,next.outfits.at(-1).id);packed=withItems!==next;next=withItems;}if(save(next,packed?'搭配与布局已保存，装备已加入待核对清单。':f.has('pack')?'搭配已保存；本次清单已满，未能加入装备。':'搭配与布局已保存。')){closeModal();if(packed){filter='pending';packingStage='pack';setTab('packing');}}});
}
function tripDialog(){showModal('下一次，去滑雪。',`<form id="trip-form"><div class="field"><label for="trip-name">给这次出发起个名字</label><input id="trip-name" name="name" maxlength="60" value="周末去滑雪" required></div><div class="field"><label for="trip-sport">这次滑什么</label><select name="sport" id="trip-sport"><option value="snowboard">单板</option><option value="ski">双板</option><option value="both" selected>单板 + 双板</option></select></div><label class="inline-field"><input name="overnight" type="checkbox">需要过夜，加上换洗与洗漱用品</label><label class="inline-field"><input name="camera" type="checkbox">带 Insta360，加入拍摄基础包与检查项</label><p class="form-note">每次出发都从未勾选的清单开始。设为每次提醒的装备会自动带上，衣橱和搭配保留。</p><div class="form-actions"><button class="primary" type="submit">开始整理 ${icon('arrow',17)}</button></div></form>`);$('#trip-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);if(state.trips.length>=100){toast('行程已达上限，请先导出备份。');return;}const next=clone();const trip=createTrip({name:data.get('name').trim(),sport:data.get('sport'),overnight:data.has('overnight'),camera:data.has('camera')},state.customTemplates);next.trips.push(trip);next.activeTripId=trip.id;if(save(next,'新清单准备好了，每件都重新核对。')){filter='pending';packingStage='pack';closeModal();setTab('packing');}});}
function catalogDialog(){
  const trip=getActiveTrip(state), entries=getCatalogItems(trip);
  const libraryGroups=[...GEAR_GROUPS.filter(g=>['nutrition','camera'].includes(g.id)),...GEAR_GROUPS.filter(g=>!['nutrition','camera'].includes(g.id))];
  const selected=new Set(entries.filter(e=>(e.default&&(!e.overnight||trip.overnight))&&!catalogItemInTrip(trip,e)).map(e=>e.key));
  const matches=(e,q)=>!q||`${e.name} ${e.category} ${e.note||''}`.toLowerCase().includes(q.toLowerCase());
  showModal('查漏补缺，按这次来。',`<form id="catalog-form"><p class="small-note">${entries.length} 项装备与出发检查。先勾选缺少的常用项；拍摄可点「选拍摄基础」，其余按本次需要添加。</p><div class="field catalog-search"><label for="gear-search">找装备</label><input id="gear-search" type="search" placeholder="搜能量胶、镜头、充电器…" autocomplete="off"></div><div class="catalog-shortcuts"><button type="button" class="category-chip" data-pick="common">选常用</button><button type="button" class="category-chip" data-pick="nutrition">选补给</button><button type="button" class="category-chip" data-pick="camera">选拍摄基础</button><button type="button" class="text-button" data-pick="clear">清空选择</button></div><div id="catalog-groups">${libraryGroups.map(g=>{
    const groupEntries=entries.filter(e=>e.group===g.id);if(!groupEntries.length)return '';
    return `<details class="catalog-group" data-gear-group="${esc(g.id)}" ${['nutrition','camera'].includes(g.id)?'open':''}><summary><span>${esc(g.label)}</span><small>${groupEntries.length} 项</small></summary><p class="catalog-group-note">${esc(g.description)}</p>${groupEntries.map(e=>{const item=trip.items.find(i=>i.templateKey===e.key||i.name===e.name);const included=Boolean(item&&item.status!=='skip');return `<label class="catalog-option ${included?'included':''}" data-catalog-key="${esc(e.key)}"><input type="checkbox" name="gear" value="${esc(e.key)}" ${included?'disabled':''} ${selected.has(e.key)?'checked':''}><span><strong>${esc(e.name)}</strong>${e.note?`<small>${esc(e.note)}</small>`:''}</span><em>${included?'已在清单':item?.status==='skip'?'恢复待装':e.default?'默认核对':e.cameraDefault?'拍摄基础':'按需'}</em></label>`;}).join('')}</details>`;
  }).join('')}</div><p id="catalog-empty" class="form-note" hidden>没有找到，可关闭后用「加装备」自行添加。</p><div class="catalog-footer"><p id="catalog-error" class="photo-error" role="status" hidden></p><label class="inline-field"><input type="checkbox" id="catalog-remember" name="remember" checked>以后每次也提醒我</label><button class="primary full-button" type="submit" id="catalog-submit">补进当前行程 · ${selected.size} 项</button><p class="form-note">新增项从待装开始，原来的勾选、数量与历史行程保留。</p></div></form>`);
  const form=$('#catalog-form');
  const update=()=>{$('#catalog-error').hidden=true;const count=selected.size;$('#catalog-submit').textContent=`补进当前行程 · ${count} 项`;$('#catalog-submit').disabled=!count;};
  form.addEventListener('change',event=>{if(event.target.name==='gear'){event.target.checked?selected.add(event.target.value):selected.delete(event.target.value);update();}});
  form.addEventListener('click',event=>{const b=event.target.closest('[data-pick]');if(!b)return;const kind=b.dataset.pick;if(kind==='clear')selected.clear();else entries.filter(e=>!catalogItemInTrip(trip,e)&&(kind==='common'?(e.default&&(!e.overnight||trip.overnight)):kind==='camera'?e.cameraDefault:e.group===kind)).forEach(e=>selected.add(e.key));form.querySelectorAll('[name="gear"]').forEach(el=>el.checked=selected.has(el.value));update();});
  $('#gear-search').addEventListener('input',event=>{const q=event.target.value.trim();let total=0;form.querySelectorAll('[data-gear-group]').forEach(group=>{let count=0;group.querySelectorAll('[data-catalog-key]').forEach(row=>{const found=matches(entries.find(e=>e.key===row.dataset.catalogKey),q);row.hidden=!found;if(found)count++;});group.hidden=!count;if(q)group.open=true;total+=count;});$('#catalog-empty').hidden=total>0;});
  form.addEventListener('submit',event=>{event.preventDefault();if(!selected.size)return;const next=addCatalogItems(state,[...selected],{remember:$('#catalog-remember').checked});const current=getActiveTrip(state),updated=getActiveTrip(next);const added=updated.items.filter(i=>!current.items.some(old=>old.id===i.id)).length;const restored=updated.items.filter(i=>i.status==='pending'&&current.items.some(old=>old.id===i.id&&old.status==='skip')).length;const changed=added+restored;if(next===state){toast('清单未改变，请检查是否已达到容量上限。');return;}if(save(next,changed?`已补入或恢复 ${changed} 项${changed<selected.size?'，其余项目受清单容量限制':''}。`:'已记住提醒设置，原清单保留。')){filter='pending';packingStage='pack';closeModal();setTab('packing');}else{$('#catalog-error').textContent=saveProblem||'未能保存，当前选择已保留。';$('#catalog-error').hidden=false;}});
  update();
}
function tripsDialog(){showModal('我的出发记录',`<div>${[...state.trips].reverse().map(t=>{const {gear,checks}=getTripReadiness(t);return `<button class="trip-choice ${t.id===state.activeTripId?'active':''}" data-switch-trip="${esc(t.id)}"><div><h3>${esc(t.name)}</h3><p>${sportNames[t.sport]} · ${t.overnight?'过夜':'日归'} · 装备 ${gear.ready}/${gear.total} · 检查 ${checks.ready}/${checks.total}${gear.rental?` · ${gear.rental} 项待取`:''}</p></div>${icon(t.id===state.activeTripId?'check':'arrow',18)}</button>`;}).join('')}</div><button class="primary full-button" data-action="new-trip">${icon('plus',18)}再建一次出发</button>`);}
function itemDialog(id){
 const item=getActiveTrip(state).items.find(i=>i.id===id);if(!item)return;
 showModal(item.name,`<div class="status-options">${Object.entries(STATUS_LABELS).filter(([key])=>item.category!=='出发检查'||['pending','packed','skip'].includes(key)).map(([key,label])=>`<button class="status-option ${key===item.status?'active':''}" data-set-status="${key}" data-id="${esc(id)}">${item.category==='出发检查'?({pending:'待检查',packed:'已确认',skip:'本次不查'}[key]||label):label}${key===item.status?icon('check',17):''}</button>`).join('')}</div>${item.category!=='出发检查'?`<form id="location-form" class="item-location-form"><label for="item-location">收纳位置</label><div class="location-fields"><select id="item-location" name="location">${Object.entries(PACKING_LOCATIONS).map(([key,label])=>`<option value="${key}" ${(item.packingLocation||'unassigned')===key?'selected':''}>${label}</option>`).join('')}</select><button class="secondary" type="submit">保存位置</button></div><p class="form-note">记录放在哪个包里，实际放好后再勾选。</p></form>`:''}<form id="quantity-form"><div class="field modal-section"><label for="item-qty">需要的数量</label><input id="item-qty" name="qty" type="number" inputmode="numeric" min="1" max="99" step="1" value="${item.qty}" required></div>${item.source!=='wardrobe'?`<label class="inline-field"><input type="checkbox" name="remember" ${isItemRemembered(state,id)?'checked':''}>记住这个数量，下次默认使用</label>`:''}<p class="form-note">增加已备好的数量，会回到待装状态，请重新确认。${item.source==='wardrobe'?'衣橱单品可通过「沿用这份」一起带到新行程。':''}</p><button class="secondary full-button" type="submit">保存数量</button></form>`);
 $('#location-form')?.addEventListener('submit',event=>{event.preventDefault();const location=new FormData(event.currentTarget).get('location');const next=updateItemLocation(state,id,location);if(next===state){closeModal();return;}if(save(next,'收纳位置已更新。'))closeModal();});
 $('#quantity-form').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget),remember=f.has('remember');const next=updateItemQty(state,id,Number(f.get('qty')),{remember});const remembered=remember&&isItemRemembered(next,id);if(save(next,remembered?'数量已更新，以后也按这个数量提醒。':remember?'本次数量已更新；常用装备已满，未能保存下次默认数量。':'本次数量已更新。'))closeModal();});
}
function addItemDialog(){const addingCheck=packingStage==='checks';showModal(addingCheck?'还有什么要检查？':'还有什么要带？',`<form id="item-form"><div class="field"><label for="custom-name">${addingCheck?'检查项目':'装备名称'}</label><input id="custom-name" name="name" maxlength="80" placeholder="${addingCheck?'比如：确认雪票与租赁预约':'比如：备用雪镜镜片'}" required></div><div class="form-grid"><div class="field"><label for="custom-category">放在哪一组</label><select id="custom-category" name="category">${[...new Set(['滑行装备','穿戴','随身','过夜','可选护具',...GEAR_CATALOG.map(t=>t.category)])].map(c=>`<option ${addingCheck&&c==='出发检查'?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="custom-qty">数量</label><input id="custom-qty" name="qty" type="number" inputmode="numeric" min="1" max="99" step="1" value="1" required></div></div><label class="inline-field"><input type="checkbox" name="remember" checked>以后每次出发也提醒我</label><p class="form-note">同名装备会更新现有数量，不会重复添加。</p><div class="form-actions"><button class="primary" type="submit">${addingCheck?'加入出发检查':'加入待装清单'}</button></div></form>`);$('#item-form').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);const next=addCustomItem(state,{name:f.get('name').trim(),category:f.get('category'),qty:Number(f.get('qty'))},f.has('remember'));if(next===state){toast('未能添加，请检查名称或清单容量。');return;}if(save(next,'项目与数量已更新，请核对清单。')){filter='pending';packingStage=f.get('category')==='出发检查'?'checks':'pack';closeModal();setTab('packing');}});}
function garmentDialog(id,{continued=0,autoCutout=true}={}){
  const original=state.wardrobe.find(g=>g.id===id);let photo=original?.photo||'',cutout=original?.cutout||'',busy=false;
  showModal(original?'编辑这件装备':'加一件，上装备墙',`<form id="garment-form">${continued?`<p class="continued-note" role="status">${icon('check',16)}已连续添加 ${continued} 件，继续放下一件。</p>`:''}<label class="photo-upload ${cutout?'has-cutout':''}" id="photo-box"><span id="photo-preview">${photo?`<img src="${cutout||photo}" alt="装备预览">`:`${icon('camera',30)}<span>选一张装备照片</span>`}</span><input id="photo-file" type="file" accept="image/*" aria-label="选择装备照片"></label><label class="inline-field cutout-toggle"><input id="auto-cutout" type="checkbox" ${autoCutout?'checked':''}>选图后自动抠图，原照片保留</label><div class="cutout-controls"><button type="button" class="secondary" id="make-cutout" ${photo?'':'hidden'}>${icon('spark',16)}${cutout?'重新抠图':'自动抠图'}</button><button type="button" class="text-button" id="use-original" ${cutout?'':'hidden'}>恢复原图</button><button type="button" class="text-button" id="cancel-cutout" hidden>停止抠图</button><button type="button" class="text-button" id="clear-photo" ${photo?'':'hidden'}>移除照片</button></div><p class="cutout-progress" id="cutout-progress" role="status" hidden></p><p class="photo-error" id="photo-error" role="status"></p><div class="field"><label for="garment-name">名字</label><input id="garment-name" name="name" maxlength="80" placeholder="比如：Burton 绿色雪服" value="${esc(original?.name||'')}" required></div><div class="form-grid"><div class="field"><label for="garment-category">类别</label><select id="garment-category" name="category">${Object.entries(CATEGORIES).map(([key,label])=>`<option value="${key}" ${original?.category===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="garment-color">主要颜色</label><select id="garment-color" name="color">${COLORS.map(c=>`<option value="${c.id}" ${original?.color===c.id?'selected':''}>${c.label}</option>`).join('')}</select></div></div><p class="form-note">照片在当前浏览器抠图；连接设备同步后，保存的照片会同步至你的私有空间。首次会加载抠图资源。建议单独平铺或挂起拍摄装备；上身照可能保留人物。背景简单更容易抠干净，不满意可以恢复原图。</p><p class="photo-error" id="garment-save-error" role="status" hidden></p><div class="form-actions garment-save-actions">${original?'<button type="button" class="danger" id="remove-garment">删除</button>':'<button type="submit" class="secondary" id="save-next-garment" name="intent" value="continue">保存并继续添加</button>'}<button type="submit" class="primary" id="save-garment">${original?'保存修改':'保存并上墙'}</button></div></form>`);
  function showPhoto(){if(!modal.open)return;$('#photo-preview').innerHTML=photo?`<img src="${cutout||photo}" alt="装备预览">`:`${icon('camera',30)}<span>选一张装备照片</span>`;$('#photo-box').classList.toggle('has-cutout',Boolean(cutout));$('#clear-photo').hidden=!photo;$('#make-cutout').hidden=!photo;$('#make-cutout').textContent=cutout?'重新抠图':'自动抠图';$('#use-original').hidden=!cutout;}
  function setBusy(value){busy=value;$('#save-garment').disabled=value;if($('#save-next-garment'))$('#save-next-garment').disabled=value;$('#make-cutout').disabled=value;$('#cancel-cutout').hidden=!value;}
  async function runCutout(){if(!photo||busy)return;const source=photo,request=++photoToken;activeCutout?.abort();const task=new AbortController();activeCutout=task;setBusy(true);$('#photo-error').textContent='';$('#cutout-progress').hidden=false;$('#cutout-progress').textContent='正在准备本地抠图…';try{const {removeBackground}=await import('./cutout.mjs?v=alpine-v7.1');if(task.signal.aborted)return;const result=await removeBackground(source,{signal:task.signal,onProgress:message=>{if(request===photoToken&&modal.open)$('#cutout-progress').textContent=message;}});if(request!==photoToken||!modal.open||photo!==source)return;if(result.length>1500000)throw new Error('抠图结果太大，原图仍然保留。可以换一张背景更简单的照片。');cutout=result;showPhoto();$('#cutout-progress').textContent='抠图完成，保存后就能作为贴纸摆放。';}catch(error){if(request===photoToken&&modal.open){$('#cutout-progress').hidden=true;if(error.name!=='AbortError')$('#photo-error').textContent=error.message||'这次抠图没完成，原照片仍保留，可以重试。';}}finally{if(request===photoToken&&modal.open){setBusy(false);activeCutout=null;}}}
  const fileInput=$('#photo-file');
  fileInput.addEventListener('change',async()=>{const file=fileInput.files?.[0];if(!file)return;activeCutout?.abort();activeCutout=null;const request=++photoToken;setBusy(true);$('#cancel-cutout').hidden=true;$('#cutout-progress').hidden=true;$('#photo-error').textContent='正在读取照片…';try{const result=await compressImage(file);if(request!==photoToken||!modal.open)return;photo=result;cutout='';showPhoto();$('#photo-error').textContent='';if(!$('#garment-name').value.trim())$('#garment-name').value=file.name.replace(/\.[^.]+$/,'').slice(0,80);setBusy(false);if($('#auto-cutout').checked)await runCutout();}catch(error){if(request===photoToken&&modal.open)$('#photo-error').textContent=error.message;}finally{if(request===photoToken&&modal.open){setBusy(false);fileInput.value='';}else if(modal.open&&$('#photo-file')===fileInput)fileInput.value='';}});
  $('#make-cutout').addEventListener('click',runCutout);
  $('#cancel-cutout').addEventListener('click',()=>{activeCutout?.abort();activeCutout=null;photoToken++;setBusy(false);$('#cutout-progress').hidden=false;$('#cutout-progress').textContent='已停止，当前照片和上次抠图结果都保留。';});
  $('#use-original').addEventListener('click',()=>{activeCutout?.abort();activeCutout=null;photoToken++;setBusy(false);cutout='';showPhoto();$('#cutout-progress').hidden=true;$('#photo-error').textContent='';});
  $('#clear-photo').addEventListener('click',()=>{activeCutout?.abort();activeCutout=null;photoToken++;setBusy(false);photo='';cutout='';showPhoto();$('#cutout-progress').hidden=true;$('#photo-error').textContent='';});
  $('#garment-form').addEventListener('submit',event=>{event.preventDefault();if(busy)return;const f=new FormData(event.currentTarget);const name=f.get('name').trim();if(!name){$('#garment-save-error').hidden=false;$('#garment-save-error').textContent='先给这件装备起个名字。';return;}const garment={id:original?.id||uid('garment'),name,category:f.get('category'),color:f.get('color'),photo,...(cutout?{cutout}:{})};let next=clone();if(original)next.wardrobe=next.wardrobe.map(g=>g.id===id?garment:g);else{next.wardrobe.push(garment);next=addBoardPiece(next,garment.id);}const keepAdding=!original&&event.submitter?.value==='continue',nextAuto=$('#auto-cutout').checked;if(save(next,original?'装备已更新，画板位置保留。':'已保存并贴上装备墙。')){if(keepAdding){garmentDialog(undefined,{continued:continued+1,autoCutout:nextAuto});modal.scrollTop=0;$('#photo-file').focus({preventScroll:true});}else closeModal();}else{$('#garment-save-error').hidden=false;$('#garment-save-error').textContent=saveProblem;}});
  $('#remove-garment')?.addEventListener('click',()=>{if(!confirm('删除这件装备？画板贴纸与搭配中的这件装备会移除，已有行程记录保留。'))return;if(save(removeGarment(state,id),'装备已删除，已有行程记录保留。'))closeModal();});
}
async function compressImage(file){if(file.size>20*1024*1024)throw new Error('照片太大，请选择 20 MB 以内的图片。');if(file.type&&!file.type.startsWith('image/')&&file.type!=='application/octet-stream')throw new Error('请选择照片文件。');const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('这张照片暂时读不了，请换成 JPG、PNG 或 WebP。'));image.src=url;});if(!image.width||!image.height)throw new Error('这张照片没有有效画面。');let size=700;for(let attempt=0;attempt<3;attempt++){const scale=Math.min(1,size/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data;let alpha=false;for(let i=3;i<pixels.length;i+=4){if(pixels[i]<255){alpha=true;break;}}const result=canvas.toDataURL(alpha?'image/png':'image/jpeg',.82);if(result.length<=1500000)return result;size=Math.round(size*.75);}throw new Error('这张照片保存后仍太大，请缩小图片后重试。');}finally{URL.revokeObjectURL(url);}}
function buildOutfitDialog(){if(!state.wardrobe.length){toast('先放几件已有单品，再自由搭配。');setTab('wardrobe');return;}showModal('选一套自己的搭配',`<form id="outfit-form"><div class="field"><label for="outfit-name">给这套起个名字</label><input id="outfit-name" name="name" maxlength="60" placeholder="比如：周末的绿色那套" required></div><p class="form-note">外套、雪裤、雪镜…想带的可以一起选。每个格子都是你的已有单品。</p>${state.wardrobe.map(g=>`<label class="checkbox-card"><input type="checkbox" name="garments" value="${esc(g.id)}">${g.photo?`<img src="${g.cutout||g.photo}" alt="">`:icon(categoryIcon(g.category),28)}<span>${esc(g.name)}<br><small>${CATEGORIES[g.category]} · ${colorFor(g.color).label}</small></span></label>`).join('')}<div class="form-actions"><button type="submit" class="primary">存好这套</button></div></form>`);$('#outfit-form').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);const garmentIds=f.getAll('garments');if(!garmentIds.length){toast('至少选一件单品。');return;}const next=clone();next.outfits.push({id:uid('outfit'),name:f.get('name').trim(),garmentIds});if(save(next,'搭配已存好，可以加入本次清单。'))closeModal();});}
function saveSuggestion(index){const suggestion=suggestOutfits(state.wardrobe)[Number(index)];if(!suggestion)return;const already=state.outfits.find(o=>o.garmentIds.length===suggestion.garmentIds.length&&o.garmentIds.every(id=>suggestion.garmentIds.includes(id)));if(already){toast('这套已经存好了，在上方「我存好的搭配」里。');return;}const first=state.wardrobe.find(g=>g.id===suggestion.garmentIds[0]);const next=clone();next.outfits.push({id:uid('outfit'),name:`${colorFor(first.color).label}外套的搭配`,garmentIds:suggestion.garmentIds});save(next,'这套存好了。');}
function download(content,name,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function packingMoreDialog(){showModal('整理这次出发',`<div class="packing-menu">${[['add-item',packingStage==='checks'?'加检查':'加装备','plus'],['catalog','装备库','bag'],['scenarios','场景补齐','route'],['trips','切换行程','ticket'],['reuse-trip','沿用这份','refresh'],['new-trip','新出发','ski'],['reset','重新核对','refresh'],['sync','设备同步','refresh']].map(([action,label,i])=>`<button class="secondary full-button" data-action="${action}">${icon(i,18)}${label}</button>`).join('')}</div>`);}
